<?php

namespace Tests\Support;

use Illuminate\Http\UploadedFile;

/**
 * Gambar contoh untuk tes tanpa GD (di mesin dev tidak terpasang): PNG dirakit
 * langsung dengan zlib, JPEG berupa berkas kecil bawaan.
 */
final class SampleImages
{
    /** JPEG 420 x 297 piksel, satu warna (krem), ±5 KB. */
    private const JPEG_420X297 = '';

    /**
     * Berkas unggahan PNG sungguhan tanpa GD.
     *
     * @param  bool  $alpha  true = PNG RGBA (transparan, colorType 6)
     */
    public static function pngUpload(string $name = 'templat.png', int $width = 420, int $height = 297, bool $alpha = false): UploadedFile
    {
        return UploadedFile::fake()->createWithContent($name, self::png($width, $height, $alpha));
    }

    /**
     * PNG abu-abu 8-bit (1 byte per piksel): murah dibuat walau ukurannya besar.
     */
    public static function grayPngUpload(string $name, int $width, int $height): UploadedFile
    {
        $chunk = fn (string $type, string $data) => pack('N', strlen($data))
            .$type.$data.pack('N', crc32($type.$data));

        $raw = str_repeat("\0".str_repeat("\xF0", $width), $height);

        return UploadedFile::fake()->createWithContent(
            $name,
            "\x89PNG\r\n\x1a\n"
                .$chunk('IHDR', pack('NNCCCCC', $width, $height, 8, 0, 0, 0, 0))
                .$chunk('IDAT', gzcompress($raw, 1))
                .$chunk('IEND', '')
        );
    }

    public static function jpegUpload(string $name = 'templat.jpg'): UploadedFile
    {
        return UploadedFile::fake()->createWithContent($name, base64_decode(self::JPEG_420X297));
    }

    public static function png(int $width, int $height, bool $alpha = false): string
    {
        $row = "\0".str_repeat($alpha ? "\xFA\xF6\xE8\xFF" : "\xFA\xF6\xE8", $width);
        $raw = str_repeat($row, $height);

        $chunk = fn (string $type, string $data) => pack('N', strlen($data))
            .$type.$data.pack('N', crc32($type.$data));

        return "\x89PNG\r\n\x1a\n"
            .$chunk('IHDR', pack('NNCCCCC', $width, $height, 8, $alpha ? 6 : 2, 0, 0, 0))
            .$chunk('IDAT', gzcompress($raw, 9))
            .$chunk('IEND', '');
    }
}
